import numpy as np, heapq, os
from PIL import Image,ImageDraw
from scipy import ndimage as ndi
S=np.load('/app/runs/target_shape.npz')
MASK=S['mask'];SKEL=S['skeleton'];D=S['distance']
YX=np.argwhere(SKEL);index={tuple(p):i for i,p in enumerate(YX)}
adj=[[] for _ in YX]
for i,(y,x) in enumerate(YX):
 for dy in [-1,0,1]:
  for dx in [-1,0,1]:
   if not (dy or dx):continue
   j=index.get((y+dy,x+dx))
   if j is not None:
    # Remove diagonal corner shortcut if both orthogonal neighbors on skeleton.
    if dy and dx and ((y+dy,x) in index or (y,x+dx) in index):continue
    adj[i].append((j,(dx*dx+dy*dy)**.5))

def nearest(p):
 p=np.array(p);return int(np.argmin(np.sum((YX-p)**2,axis=1)))

def path(a,b):
 s=nearest(a);t=nearest(b);di={s:0};pred={};pq=[(0,s)]
 while pq:
  d,i=heapq.heappop(pq)
  if i==t:break
  if d>di[i]:continue
  for j,w in adj[i]:
   v=d+w
   if v<di.get(j,1e10):di[j]=v;pred[j]=i;heapq.heappush(pq,(v,j))
 if t not in di:raise RuntimeError(f'not connected: {a} {b}')
 z=[t]
 while z[-1]!=s:z.append(pred[z[-1]])
 return YX[z[::-1]]

def waypath(points):
 return np.concatenate([path(a,b) if i==0 else path(a,b)[1:] for i,(a,b) in enumerate(zip(points[:-1],points[1:]))])

def resample(P,step=4.0):
 P=np.array(P,float);dd=np.hypot(np.diff(P[:,0]),np.diff(P[:,1]));cum=np.concatenate([[0],np.cumsum(dd)]);t=np.arange(0,cum[-1],step);t=np.r_[t,cum[-1]]
 return np.column_stack([np.interp(t,cum,P[:,0]),np.interp(t,cum,P[:,1])])

def render(P,out):
 a=np.asarray(Image.open('/app/target.png')).copy();im=Image.fromarray(a);d=ImageDraw.Draw(im)
 for p,q in zip(P[:-1],P[1:]):d.line((p[1],p[0],q[1],q[0]),fill=(255,0,200),width=3)
 for i,p in enumerate(P[::max(1,len(P)//20)]):d.ellipse((p[1]-2,p[0]-2,p[1]+2,p[0]+2),fill=(0,255,0))
 im.save(out)

def footprint(P):
 o=np.zeros(MASK.shape,bool)
 for v,u in P:
  y=int(round(v));x=int(round(u));r=float(D[y,x]);R=int(np.ceil(r));yy,xx=np.ogrid[-R:R+1,-R:R+1];b=xx*xx+yy*yy<r*r
  v0=max(y-R,0);v1=min(y+R+1,1024);u0=max(x-R,0);u1=min(x+R+1,1024)
  o[v0:v1,u0:u1]|=b[v0-y+R:v1-y+R,u0-x+R:u1-x+R]
 return o

if __name__=='__main__':
 W=[(393,293),(292,559),(480,530),(645,588),(706,701),(541,673),(706,701),(734,741)]
 P=resample(waypath(W));print('route points',len(P),'length mm',len(P)*4*.22186,'planned',P[[0,-1]])
 render(P,'/app/runs/plan1.png');O=footprint(P);print('covered', (O&MASK).sum()/MASK.sum(),'stray',(O&~MASK).sum()/MASK.sum())
 np.save('/app/runs/plan1.npy',P)
